function depthSumInverse(nestedList) {
  let level = nestedList;
  let runningSum = 0;
  let total = 0;

  while (level.length > 0) {
    const nextLevel = [];
    for (const item of level) {
      if (item.isInteger()) {
        runningSum += item.getInteger();
      } else {
        for (const child of item.getList()) {
          nextLevel.push(child);
        }
      }
    }
    total += runningSum;
    level = nextLevel;
  }
  return total;
}

