function depthSumInverse(nestedList) {
  // First pass: the deepest integer. Second pass: weight each integer directly.
  const deepest = (list, depth) => {
    let best = 0;
    for (const item of list) best = Math.max(best, item.isInteger() ? depth : deepest(item.getList(), depth + 1));
    return best;
  };
  const maxDepth = deepest(nestedList, 1);
  const weighted = (list, depth) => {
    let sum = 0;
    for (const item of list) sum += item.isInteger() ? item.getInteger() * (maxDepth - depth + 1) : weighted(item.getList(), depth + 1);
    return sum;
  };
  return weighted(nestedList, 1);
}

