function generate(rand, size) {
  const large = size === 'large';
  const maxDepth = large ? 10 : 1 + Math.floor(rand() * 5);
  const span = large || rand() < 0.4 ? 100 : 5;
  const value = () => Math.floor(rand() * (2 * span + 1)) - span;
  // A list whose own integers sit at the given depth; it always has at least one element.
  const makeList = (depth) => {
    const length = 1 + Math.floor(rand() * (large ? 5 : 3));
    const list = [];
    for (let i = 0; i < length; i++) list.push(depth < maxDepth && rand() < 0.45 ? makeList(depth + 1) : value());
    return list;
  };
  const top = large ? 50 : 1 + Math.floor(rand() * 5);
  const nestedList = [];
  for (let i = 0; i < top; i++) nestedList.push(maxDepth > 1 && rand() < 0.5 ? makeList(2) : value());
  return [nestedList];
}
